def f(g):
    h,w=len(g),len(g[0])
    lr=[r for r in range(h) if 2 in g[r]][0]
    out=[[0]*w for _ in range(h)]
    for r,c in [(rr,cc) for rr in range(h) for cc in range(w) if g[rr][cc]==4]:
        # vertex adjacent to source toward the line? demo: source(4,2), lr=6, vertex=(5,2) i.e. r+side
        side=1 if r<lr else -1
        vr=r+side
        vrow,vcol=vr,c
        painted=[]
        # cap row: farthest row from line such that arms fit; walk up/down
        steps=0
        while True:
            cr=vrow-side*(steps+1); cl_left=c-(steps+1); cl_right=c+(steps+1)
            if 0<=cr<h and 0<=cl_left<w and 0<=cl_right<w:
                steps+=1
            else:
                break
        for k in range(steps):
            pr,vl=vr-side*k, c-(k+1)
            pr,vr2=vr-side*k, c+(k+1)
            if 0<=pr<h and 0<=vl<w: painted.append((pr,vl))
            if 0<=pr<h and 0<=vr2<w: painted.append((pr,vr2))
        # vertex
        painted.append((vrow,vcol))
        for pr,pv in painted:
            if g[pr][pv]==0: out[pr][pv]=4
    return out
