        k=i-j; 
        # down-left arm
        x,y=i,j
        while 0<=x+1<H and 0<=y-1<W: x+=1;y-=1; o[x][y]=4
        # up-right arm
        x,y=i,j
        while 0<=x-1<H and 0<=y+1<W: x-=1;y+=1; o[x][y]=4
