def solve(I,out=None,debug=False):
    H,W=len(I),len(I[0])
    br=[r for r in range(H) if all(x==2 for x in I[r])][0]
    S=[(r,c) for r in range(H) for c in range(W) if I[r][c]==4]
    def dirs_up(): return [(-1,-1),(-1,1)]
    def dirs_down(): return [(1,-1),(1,1)]
    D=dirs_up if max(br) < H-1 else dirs_down
    # actually determine: if source above bar -> away = up
    def away_dirs(sr):
        return dirs_up() if sr<br else dirs_down()
    out=[row[:] for row in I]; painted=set()
    order=S  # will experiment
    for sr,sc in S:
        for dd in away_dirs(sr):
            r,c=sr+dd[0],sc+dd[1]
            while 0<=r<H and 0<=c<W and I[r][c]==0:
                if any(abs(r-p[0])<=1 and abs(c-p[1])<=1 for p in painted): break
                out[r][c]=4; painted.add((r,c)); r+=dd[0]; c+=dd[1]
        foot=(sr+(dr if False else 0),sc)
        sgn=1 if sr<br else -1
        f=(sr+sgn,sc)
        if 0<=f[0]<H and 0<=f[1]<W and I[f[0]][f[1]]==0 and out[f[0]][f[1]]==0:
            out[f[0]][f[1]]=4; painted.add(f)
    for sr,sc in S: out[sr][sc]=0
    return out
